import pathlib,struct,json
reports=[]
for folder in pathlib.Path("/work").glob("active-*/private-backing/workspace"):
 pages=[]
 for p in folder.glob("a-*"):
  b=p.read_bytes();kind=struct.unpack(">H",b[10:12])[0]
  entry={"name":p.name,"kind":kind,"revision":struct.unpack(">Q",b[68:76])[0],"used":struct.unpack(">H",b[76:78])[0],"records":struct.unpack(">H",b[78:80])[0]}
  if kind==4: entry["slots"]=[{"slot":s,"epoch":struct.unpack(">Q",b[136+s*32:144+s*32])[0],"page":struct.unpack(">Q",b[144+s*32:152+s*32])[0],"level":b[160+s*32],"kind":b[161+s*32]} for s in range(64) if any(b[136+s*32:144+s*32])]
  if kind==3:
   at=128;cells=[]
   for i in range(entry["records"]):
    n=struct.unpack(">H",b[at:at+2])[0];at+=2;fence=b[at:at+n].hex();at+=n;tag=b[at];first,epoch=struct.unpack(">QQ",b[at+1:at+17]);at+=17;cells.append({"fence":fence,"tag":tag,"first":first,"epoch":epoch})
   entry["children"]=cells
  pages.append(entry)
 reports.append({"folder":str(folder),"pages":pages})
print(json.dumps(reports,indent=2))
